sp_widget.client_script:
api.controller=function($scope) {
/* widget controller */
var c = this;
$scope.prompt;
$scope.message = [];

$scope.addAssistantMessage = function(role, msg){
    $scope.message.push(
        {"role": role, "content": msg}
    );
};

$scope.streamResponse= function(){
	try{

         $scope.addAssistantMessage("user", $scope.prompt);

		var apiKey = "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";
    var response =  fetch("https://api.openai.com/v1/chat/completions", {
        method: "POST",
        headers: {
            "Content-Type": "application/json",
            "Authorization": "Bearer " + apiKey
        },
        body: JSON.stringify({
            model: "gpt-4o-mini", 
            messages: $scope.message,
            stream: true
        })
    }).then(function(response) {
        var reader = response.body.getReader();
        var decoder = new TextDecoder("utf-8");

        function readChunk() {
            return reader.read().then(function(result) {
                if (result.done) return;

                var chunk = decoder.decode(result.value, { stream: true });
                var lines = chunk.split("\n").filter(function(line) {
                    return line.trim() !== "";
                });

                lines.forEach(function(line) {
                    if (line.startsWith("data: ")) {
                        var data = line.replace(/^data: /, "");
                        if (data === "[DONE]") {
                            $scope.addAssistantMessage("system", $scope.output);
                            $scope.output = "";
                            return;
                        }



                        try {
                            var parsed = JSON.parse(data);
                            var content = parsed.choices[0].delta.content || "";


                            $scope.$apply(function() {
                                $scope.output += content;
                            });


                        } catch (err) {
                            console.error(err);
                        }
                    }
                });

                return readChunk();
            });
        }

        return readChunk();
    })
	 }catch(error){
		 console.log("ERROR == "+ error);
	 }



};


};

sp_widget.css:
.chat-container {
  width: 100%;
  max-width: 800px;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  height: 80vh;
  border: 1px solid #ccc;
  border-radius: 8px;
  overflow: hidden;
  background: #f5f5f5;
}

.chat-messages {
  flex: 1;
  padding: 16px;
  overflow-y: auto;
}

.chat-message {
  margin-bottom: 10px;
  display: flex;
  align-items: flex-start;
}

.user-message {
  align-self: flex-end;
  background: #0084ff;
  color: white;
  border-radius: 16px;
  margin-left: auto;
  padding: 8px 12px;
  max-width: 60%;
}

.assistant-message {
  background: #e4e6eb;
  border-radius: 16px;
  padding: 8px 12px;
  max-width: 60%;
}

.message-content {
  font-size: 14px;
  line-height: 1.4;
}

.chat-input-form {
  display: flex;
  border-top: 1px solid #ccc;
  background: white;
}

.chat-input {
  flex: 1;
  padding: 10px 12px;
  border: none;
  outline: none;
  font-size: 16px;
}

.send-button {
  background: #0084ff;
  border: none;
  color: white;
  padding: 10px 16px;
  cursor: pointer;
  transition: background 0.3s;
}

.send-button:hover {
  background: #006bbf;
}
